 1→/**
 2→ * Sustained Load Scenario
 3→ *
 4→ * N clients running at a steady rate for a configurable duration.
 5→ * Tests latency stability over time — detects memory leaks, connection
 6→ * pool exhaustion, and other time-dependent degradation.
 7→ */
 8→
 9→import { describe, it, afterAll } from 'vitest';
10→import {
11→  createClientPool,
12→  destroyClientPool,
13→  aggregateAndReport,
14→  type PoolClient,
15→} from '../harness/client-pool';
16→
17→const NUM_CLIENTS = parseInt(process.env.LOAD_TEST_CLIENTS ?? '5', 10);
18→const DURATION_SEC = parseInt(process.env.LOAD_TEST_DURATION ?? '300', 10);
19→const OPS_PER_SEC_PER_CLIENT = 2;
20→
21→describe('Sustained Load', () => {
22→  let pool: PoolClient[] = [];
23→
24→  afterAll(async () => {
25→    await destroyClientPool(pool);
26→  });
27→
28→  it(`${NUM_CLIENTS} clients × ${OPS_PER_SEC_PER_CLIENT} ops/sec for ${DURATION_SEC}s`, async () => {
29→    pool = await createClientPool({
30→      clientCount: NUM_CLIENTS,
31→      label: 'sustained',
32→    });
33→
34→    const endTime = Date.now() + DURATION_SEC * 1000;
35→
36→    const results = await Promise.allSettled(
37→      pool.map((pc) => runSustainedClient(pc, endTime, OPS_PER_SEC_PER_CLIENT))
38→    );
39→
40→    const succeeded = results.filter((r) => r.status === 'fulfilled').length;
41→    console.log(`\nClients completed: ${succeeded}/${pool.length}`);
42→
43→    await aggregateAndReport('Sustained Load', pool);
44→  });
45→});
46→
47→async function runSustainedClient(
48→  pc: PoolClient,
49→  endTime: number,
50→  opsPerSec: number
51→): Promise<void> {
52→  const { client, rootIpnsName, metrics } = pc;
53→  metrics.start();
54→
55→  const intervalMs = 1000 / opsPerSec;
56→  let folderCounter = 0;
57→
58→  while (Date.now() < endTime) {
59→    const opStart = Date.now();
60→
61→    try {
62→      // Alternate between folder create and delete to keep state manageable
63→      const name = `sustained-${pc.id}-${folderCounter++}`;
64→
65→      const folder = await metrics.measure('createFolder', () =>
66→        client.createFolder(rootIpnsName, name)
67→      );
68→
69→      // Small file upload
70→      const data = new Uint8Array(1024);
71→      crypto.getRandomValues(data);
72→      await metrics.measure(
73→        'uploadFile',
74→        () => client.uploadFile(rootIpnsName, data, `${name}.bin`, 'application/octet-stream'),
75→        1024
76→      );
77→
78→      // Cleanup to prevent state bloat
79→      const folderState = client.getFolderTree().get(rootIpnsName);
80→      const fileChild = folderState?.children.find((c) => c.name === `${name}.bin`);
81→      if (fileChild) {
82→        await metrics.measure('deleteItem', () => client.deleteItem(rootIpnsName, fileChild.id));
83→      }
84→      await metrics.measure('deleteItem', () => client.deleteItem(rootIpnsName, folder.id));
85→    } catch {
86→      // Non-fatal — continue the sustained load
87→    }
88→
89→    // Wait for next interval
90→    const elapsed = Date.now() - opStart;
91→    const wait = Math.max(0, intervalMs - elapsed);
92→    if (wait > 0) {
93→      await new Promise((r) => setTimeout(r, wait));
94→    }
95→  }
96→
97→  metrics.stop();
98→}
99→

 1→/**
 2→ * IPNS Publish Storm Scenario
 3→ *
 4→ * N clients performing rapid folder mutations, each triggering IPNS publish.
 5→ * Tests IPNS publish contention — the known system bottleneck.
 6→ */
 7→
 8→import { describe, it, afterAll } from 'vitest';
 9→import {
10→  createClientPool,
11→  destroyClientPool,
12→  aggregateAndReport,
13→  type PoolClient,
14→} from '../harness/client-pool';
15→import { runFolderWorkload } from '../workloads/folder-workload';
16→
17→const NUM_CLIENTS = parseInt(process.env.LOAD_TEST_CLIENTS ?? '20', 10);
18→const CYCLES_PER_CLIENT = 50;
19→
20→describe('IPNS Publish Storm', () => {
21→  let pool: PoolClient[] = [];
22→
23→  afterAll(async () => {
24→    await destroyClientPool(pool);
25→  });
26→
27→  it(`${NUM_CLIENTS} clients × ${CYCLES_PER_CLIENT} folder create-rename-delete cycles`, async () => {
28→    pool = await createClientPool({
29→      clientCount: NUM_CLIENTS,
30→      label: 'ipns-storm',
31→    });
32→
33→    const results = await Promise.allSettled(
34→      pool.map((pc) => {
35→        pc.metrics.start();
36→        return runFolderWorkload(pc, { cycles: CYCLES_PER_CLIENT }).finally(() =>
37→          pc.metrics.stop()
38→        );
39→      })
40→    );
41→
42→    const succeeded = results.filter((r) => r.status === 'fulfilled').length;
43→    console.log(`\nClients completed: ${succeeded}/${pool.length}`);
44→
45→    await aggregateAndReport('IPNS Publish Storm', pool);
46→  });
47→});
48→

  1→/**
  2→ * Load Test Reporter
  3→ *
  4→ * Formats metrics into console table output and JSON export.
  5→ */
  6→
  7→import type { OperationMetrics } from './metrics';
  8→
  9→/**
 10→ * Print a formatted summary table to console.
 11→ */
 12→export function printSummary(
 13→  scenarioName: string,
 14→  metrics: OperationMetrics[],
 15→  totalDurationMs: number,
 16→  clientCount: number
 17→): void {
 18→  const totalOps = metrics.reduce((sum, m) => sum + m.count, 0);
 19→  const totalErrors = metrics.reduce((sum, m) => sum + m.errors, 0);
 20→  const totalBytes = metrics.reduce((sum, m) => sum + (m.bytesTransferred ?? 0), 0);
 21→
 22→  console.log(`\n${'='.repeat(80)}`);
 23→  console.log(`LOAD TEST: ${scenarioName}`);
 24→  console.log(`${'='.repeat(80)}`);
 25→  console.log(`Clients:     ${clientCount}`);
 26→  console.log(`Duration:    ${(totalDurationMs / 1000).toFixed(1)}s`);
 27→  console.log(`Total ops:   ${totalOps} (${totalErrors} errors)`);
 28→  const durationSec = Math.max(totalDurationMs, 1) / 1000;
 29→  console.log(`Throughput:  ${(totalOps / durationSec).toFixed(2)} ops/sec`);
 30→  if (totalBytes > 0) {
 31→    console.log(`Data:        ${formatBytes(totalBytes)}`);
 32→  }
 33→  console.log(`${'─'.repeat(80)}`);
 34→
 35→  // Table header
 36→  console.log(
 37→    padRight('Operation', 22) +
 38→      padRight('Count', 8) +
 39→      padRight('Errors', 8) +
 40→      padRight('p50', 10) +
 41→      padRight('p95', 10) +
 42→      padRight('p99', 10) +
 43→      padRight('Max', 10)
 44→  );
 45→  console.log('─'.repeat(80));
 46→
 47→  for (const m of metrics) {
 48→    console.log(
 49→      padRight(m.operation, 22) +
 50→        padRight(String(m.count), 8) +
 51→        padRight(String(m.errors), 8) +
 52→        padRight(fmtMs(m.latency.p50), 10) +
 53→        padRight(fmtMs(m.latency.p95), 10) +
 54→        padRight(fmtMs(m.latency.p99), 10) +
 55→        padRight(fmtMs(m.latency.max), 10)
 56→    );
 57→  }
 58→
 59→  console.log(`${'='.repeat(80)}\n`);
 60→}
 61→
 62→/**
 63→ * Export metrics as JSON (for CI artifact upload).
 64→ */
 65→export function toJsonReport(
 66→  scenarioName: string,
 67→  metrics: OperationMetrics[],
 68→  totalDurationMs: number,
 69→  clientCount: number
 70→): string {
 71→  return JSON.stringify(
 72→    {
 73→      scenario: scenarioName,
 74→      clientCount,
 75→      totalDurationMs,
 76→      totalOps: metrics.reduce((sum, m) => sum + m.count, 0),
 77→      totalErrors: metrics.reduce((sum, m) => sum + m.errors, 0),
 78→      operations: metrics,
 79→      timestamp: new Date().toISOString(),
 80→    },
 81→    null,
 82→    2
 83→  );
 84→}
 85→
 86→function padRight(str: string, len: number): string {
 87→  return str.padEnd(len);
 88→}
 89→
 90→function fmtMs(ms: number): string {
 91→  if (ms < 1000) return `${Math.round(ms)}ms`;
 92→  return `${(ms / 1000).toFixed(1)}s`;
 93→}
 94→
 95→function formatBytes(bytes: number): string {
 96→  if (bytes < 1024) return `${bytes}B`;
 97→  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)}KB`;
 98→  return `${(bytes / (1024 * 1024)).toFixed(1)}MB`;
 99→}
