  1→/**
  2→ * Upload operations - Encrypt and upload files to IPFS
  3→ *
  4→ * Extracted from: apps/web/src/services/upload.service.ts + file-crypto.service.ts
  5→ * Change: Takes raw Uint8Array data instead of File objects (no browser DOM deps).
  6→ * Change: Takes explicit SdkContext instead of reading stores.
  7→ * Does NOT handle: multi-file orchestration, upload queue, progress UI, quota checking.
  8→ */
  9→
 10→import {
 11→  generateFileKey,
 12→  generateIv,
 13→  encryptAesGcm,
 14→  wrapKey,
 15→  clearBytes,
 16→  bytesToHex,
 17→} from '@cipherbox/crypto';
 18→import type { SdkContext, TeeKeys, ProgressCallback } from '../types';
 19→import { addToIpfs } from '../ipfs';
 20→import { createFileMetadata, type FileIpnsRecordPayload } from '../file';
 21→
 22→/**
 23→ * Result of a single file upload operation.
 24→ */
 25→export type UploadResult = {
 26→  /** IPFS CID of the encrypted file content */
 27→  cid: string;
 28→  /** Encrypted file size in bytes */
 29→  encryptedSize: number;
 30→  /** File metadata IPNS name (for FilePointer) */
 31→  fileMetaIpnsName: string;
 32→  /** File IPNS record payload for batch publish */
 33→  ipnsRecord: FileIpnsRecordPayload;
 34→  /** ECIES-wrapped IPNS private key (hex) for storage in FilePointer */
 35→  ipnsPrivateKeyEncrypted: string;
 36→  /**
 37→   * Plaintext file key (AES-256) for post-upload re-wrapping.
 38→   * The caller MUST clear this with clearBytes() after use.
 39→   * Only present when the caller needs to re-wrap for share recipients.
 40→   */
 41→  fileKey: Uint8Array;
 42→};
 43→
 44→/**
 45→ * Encrypt and upload a file to IPFS, creating file metadata.
 46→ *
 47→ * This is the core single-file upload pipeline:
 48→ * 1. Generate file key + IV
 49→ * 2. Encrypt the file content with AES-256-GCM
 50→ * 3. Upload encrypted blob to IPFS
 51→ * 4. Create per-file IPNS metadata record
 52→ *
 53→ * Returns everything needed to add a FilePointer to the parent folder.
 54→ *
 55→ * @param params.data - Raw file content as Uint8Array
 56→ * @param params.fileId - Pre-generated UUID for this file
 57→ * @param params.mimeType - MIME type of the original file
 58→ * @param params.folderKey - Parent folder's decrypted AES-256 key
 59→ * @param params.userPublicKey - User's secp256k1 public key for ECIES wrapping
 60→ * @param params.ctx - SDK context for API access
 61→ * @param params.onProgress - Optional upload progress callback
 62→ * @param params.teeKeys - Optional TEE keys for IPNS private key enrollment
 63→ */
 64→export async function uploadFile(params: {
 65→  data: Uint8Array;
 66→  fileId: string;
 67→  mimeType: string;
 68→  folderKey: Uint8Array;
 69→  userPublicKey: Uint8Array;
 70→  ctx: SdkContext;
 71→  onProgress?: ProgressCallback;
 72→  teeKeys?: TeeKeys;
 73→}): Promise<UploadResult> {
 74→  // 1. Generate unique file key and IV
 75→  const fileKey = generateFileKey();
 76→  const iv = generateIv();
 77→
 78→  try {
 79→    // 2. Encrypt with AES-256-GCM
 80→    const ciphertext = await encryptAesGcm(params.data, fileKey, iv);
 81→
 82→    // 3. Wrap file key with user's public key (ECIES)
 83→    const wrappedKey = await wrapKey(fileKey, params.userPublicKey);
 84→
 85→    // 4. Upload encrypted content to IPFS
 86→    const { cid, size: encryptedSize } = await addToIpfs(params.ctx, ciphertext, params.onProgress);
 87→
 88→    // 5. Create per-file IPNS metadata record
 89→    const fileMetaResult = await createFileMetadata({
 90→      fileId: params.fileId,
 91→      cid,
 92→      fileKeyEncrypted: bytesToHex(wrappedKey),
 93→      fileIv: bytesToHex(iv),
 94→      size: params.data.length,
 95→      mimeType: params.mimeType,
 96→      folderKey: params.folderKey,
 97→      userPublicKey: params.userPublicKey,
 98→      ctx: params.ctx,
 99→      teeKeys: params.teeKeys,
100→      encryptionMode: 'GCM',
101→    });
102→
103→    // Return a defensive copy of the file key for re-wrapping.
104→    // The caller is responsible for clearing it after use.
105→    const fileKeyCopy = new Uint8Array(fileKey);
106→
107→    return {
108→      cid,
109→      encryptedSize,
110→      fileMetaIpnsName: fileMetaResult.fileMetaIpnsName,
111→      ipnsRecord: fileMetaResult.ipnsRecord,
112→      ipnsPrivateKeyEncrypted: fileMetaResult.ipnsPrivateKeyEncrypted,
113→      fileKey: fileKeyCopy,
114→    };
115→  } finally {
116→    // 6. Clear the internal copy of the key from memory
117→    clearBytes(fileKey);
118→  }
119→}
120→

  1→/**
  2→ * @cipherbox/sdk - CipherBoxClient
  3→ *
  4→ * Stateful client orchestrating folder CRUD, file upload/download,
  5→ * and event-driven change notification. Wraps @cipherbox/sdk-core
  6→ * stateless functions with internal state management (FolderTree, KeyCache).
  7→ *
  8→ * Design principles:
  9→ * - Zero React/Zustand/browser dependencies
 10→ * - All state flows through typed events (SdkEvent)
 11→ * - Operations are wrapped with withOperation() for consistent
 12→ *   start/end/error event emission
 13→ * - Key material is cleared on destroy()
 14→ */
 15→
 16→import type { SdkContext, ProgressCallback, DownloadProgressCallback } from '@cipherbox/sdk-core';
 17→import * as sdkCore from '@cipherbox/sdk-core';
 18→import { createAxiosInstance } from '@cipherbox/api-client';
 19→import { clearBytes } from '@cipherbox/crypto';
 20→import type { FolderChild } from '@cipherbox/core';
 21→import type { CipherBoxClientConfig, FolderState } from './types';
 22→import { SdkEventEmitter, type SdkEvent, type SdkEventHandler } from './events';
 23→import { FolderTree } from './state/folder-tree';
 24→import { KeyCache } from './state/key-cache';
 25→import * as binOps from './bin';
 26→import type { BinState } from './bin';
 27→import * as shareOps from './share';
 28→import type { SentShareInfo } from './share';
 29→
 30→/** Thrown when a bin operation is attempted before loadBin() has been called. */
 31→export class BinNotLoadedError extends Error {
 32→  constructor() {
 33→    super('Bin not loaded');
 34→    this.name = 'BinNotLoadedError';
 35→  }
 36→}
 37→
 38→export class CipherBoxClient {
 39→  private config: CipherBoxClientConfig;
 40→  private ctx: SdkContext;
 41→  private emitter: SdkEventEmitter;
 42→  private folderTree: FolderTree;
 43→  private keyCache: KeyCache;
 44→  private binState: BinState | null = null;
 45→  /** Internal copies of key material — zeroed on destroy() without affecting caller buffers */
 46→  private internalVaultKeypair: { publicKey: Uint8Array; privateKey: Uint8Array };
 47→  private internalRootFolderKey: Uint8Array;
 48→
 49→  constructor(config: CipherBoxClientConfig) {
 50→    // Defensive copy of key material so destroy() only zeroes our copies
 51→    this.internalVaultKeypair = {
 52→      publicKey: new Uint8Array(config.vaultKeypair.publicKey),
 53→      privateKey: new Uint8Array(config.vaultKeypair.privateKey),
 54→    };
 55→    this.internalRootFolderKey = new Uint8Array(config.rootFolderKey);
 56→    this.config = {
 57→      ...config,
 58→      vaultKeypair: this.internalVaultKeypair,
 59→      rootFolderKey: this.internalRootFolderKey,
 60→    };
 61→    const axiosInstance =
 62→      config.axiosInstance ??
 63→      createAxiosInstance({
 64→        baseUrl: config.apiUrl,
 65→        getAccessToken: config.getAccessToken,
 66→        defaultHeaders: config.defaultHeaders,
 67→      });
 68→    this.ctx = {
 69→      apiUrl: config.apiUrl,
 70→      getAccessToken: config.getAccessToken,
 71→      axiosInstance,
 72→    };
 73→    this.emitter = new SdkEventEmitter();
 74→    this.folderTree = new FolderTree();
 75→    this.keyCache = new KeyCache();
 76→  }
 77→
 78→  // ---- Event subscription ----
 79→
 80→  /** Subscribe to SDK events. Returns an unsubscribe function. */
 81→  on(handler: SdkEventHandler): () => void {
 82→    return this.emitter.on(handler);
 83→  }
 84→
 85→  /** Unsubscribe a previously registered handler. */
 86→  off(handler: SdkEventHandler): void {
 87→    this.emitter.off(handler);
 88→  }
 89→
 90→  // ---- Lifecycle ----
 91→
 92→  // ---- Share re-wrapping (internal) ----
 93→
 94→  /**
 95→   * Re-wrap keys for share recipients after adding items to a folder.
 96→   *
 97→   * Queries the share callbacks for active shares covering the folder,
 98→   * then wraps each new item's plaintext key for each recipient.
 99→   * Failures are logged but do not propagate (re-wrapping is best-effort).
100→   */

