618→          ipnsName: folderIpnsName,
619→          sequenceNumber: folder.sequenceNumber,
620→          ctx: this.ctx,
621→        });
622→
623→        // 4. Update internal state
624→        folder.children = updatedChildren;
625→        folder.sequenceNumber = newSequenceNumber;
626→        folder.lastLoadedAt = Date.now();
627→        this.folderTree.set(folderIpnsName, folder);
