 27→@ApiTags('IPNS')
 28→@ApiBearerAuth()
 29→@UseGuards(JwtAuthGuard, ThrottlerGuard)
 30→@Controller('ipns')
 31→export class IpnsController {
 32→  constructor(
 33→    private readonly ipnsService: IpnsService,
 34→    private readonly metricsService: MetricsService
 35→  ) {}
 36→
 37→  // [SECURITY: HIGH-04] Rate limit IPNS publish to prevent abuse
 38→  // Each publish makes external HTTP calls to the delegated routing service
 39→  @Throttle({ default: { limit: 10, ttl: 60000 } }) // 10 publishes per minute per user
 40→  @Post('publish')
 41→  @ApiOperation({
 42→    summary: 'Publish IPNS record',
 43→    description:
 44→      'Relay a pre-signed IPNS record to the IPFS network via delegated routing. ' +
 45→      'The client signs the record locally; backend relays to the delegated routing service and tracks ' +
 46→      'the folder for TEE republishing.',
 47→  })
 48→  @ApiResponse({
 49→    status: 200,
 50→    description: 'IPNS record published successfully',
 51→    type: PublishIpnsResponseDto,
 52→  })
 53→  @ApiResponse({
 54→    status: 400,
 55→    description: 'Bad Request - Invalid record format or missing required fields',
 56→  })
 57→  @ApiResponse({
 58→    status: 401,
 59→    description: 'Unauthorized - JWT token required',
 60→  })
 61→  @ApiResponse({
 62→    status: 409,
 63→    description:
 64→      'Conflict - expectedSequenceNumber does not match current server sequence number. ' +
 65→      'Response body includes currentSequenceNumber for client re-sync.',
 66→  })
 67→  @ApiResponse({
 68→    status: 502,
 69→    description: 'Bad Gateway - Failed to publish to delegated routing',
 70→  })
 71→  async publishRecord(
 72→    @Request() req: RequestWithUser,
 73→    @Body() dto: PublishIpnsDto
 74→  ): Promise<PublishIpnsResponseDto> {
 75→    const result = await this.ipnsService.publishRecord(req.user.id, dto);
 76→    this.metricsService.ipnsPublishes.inc({ type: 'single' });
 77→    return result;
 78→  }
 79→
 80→  // [SECURITY: HIGH-04] Rate limit batch publish - lower limit since each batch can have up to 200 records
 81→  @Throttle({ default: { limit: 5, ttl: 60000 } }) // 5 batch publishes per minute per user
 82→  @Post('publish-batch')
 83→  @ApiOperation({
 84→    summary: 'Batch publish IPNS records',
 85→    description:
 86→      'Publish multiple IPNS records (folder and/or file) in a single API call. ' +
 87→      'Supports up to 200 records per batch with concurrency-limited processing. ' +
 88→      'Partial success is allowed: individual record failures do not fail the batch.',
 89→  })
 90→  @ApiResponse({
 91→    status: 200,
 92→    description: 'Batch publish results with per-record outcomes',
 93→    type: BatchPublishIpnsResponseDto,
 94→  })
 95→  @ApiResponse({
 96→    status: 400,
 97→    description: 'Bad Request - Invalid record format or batch exceeds 200 entries',
 98→  })
 99→  @ApiResponse({
100→    status: 401,
101→    description: 'Unauthorized - JWT token required',
102→  })
103→  @ApiResponse({
104→    status: 409,
105→    description:
106→      'Conflict - a folder record in the batch has an expectedSequenceNumber that does not match ' +
107→      'the current server sequence number. The entire batch is rejected.',
108→  })
109→  @ApiResponse({
110→    status: 502,
111→    description: 'Bad Gateway - Delegated routing failures (partial results may be returned)',
112→  })
113→  async publishBatch(
114→    @Request() req: RequestWithUser,
115→    @Body() dto: BatchPublishIpnsDto
116→  ): Promise<BatchPublishIpnsResponseDto> {
117→    const result = await this.ipnsService.publishBatch(req.user.id, dto);
118→    this.metricsService.ipnsPublishes.inc({ type: 'batch' }, result.totalSucceeded);
119→    return result;
120→  }
121→
122→  // [SECURITY: HIGH-04] Rate limit IPNS resolve - higher limit than publish since read-only
123→  @Throttle({ default: { limit: 30, ttl: 60000 } }) // 30 resolves per minute per user
124→  @Get('resolve')
125→  @ApiOperation({
126→    summary: 'Resolve IPNS name',
127→    description:
128→      'Resolve an IPNS name to its current CID via delegated routing. ' +
129→      'Returns the CID and sequence number of the current IPNS record.',
130→  })
131→  @ApiQuery({
132→    name: 'ipnsName',
133→    description:
134→      'IPNS name to resolve. Supports CIDv1 IPNS names starting with "k51..." (PeerID-style) or "bafzaa..." (IPNS key CID).',
135→    example: 'REDACTED',
136→  })
137→  @ApiResponse({
138→    status: 200,
139→    description: 'IPNS name resolved successfully',
140→    type: ResolveIpnsResponseDto,
141→  })
142→  @ApiResponse({
143→    status: 400,
144→    description: 'Bad Request - Invalid IPNS name format',
145→  })
146→  @ApiResponse({
147→    status: 401,
148→    description: 'Unauthorized - JWT token required',
149→  })
150→  @ApiResponse({
151→    status: 404,
152→    description: 'Not Found - IPNS name not published or not found in routing network',
153→  })
154→  @ApiResponse({
155→    status: 502,
156→    description: 'Bad Gateway - Failed to resolve from delegated routing',
157→  })
158→  async resolveRecord(@Query() query: ResolveIpnsQueryDto): Promise<ResolveIpnsResponseDto> {
159→    const result = await this.ipnsService.resolveRecord(query.ipnsName);
160→
161→    if (!result) {
162→      throw new NotFoundException('IPNS name not found in routing network');
163→    }
164→
165→    // Track resolve source: if signatureV2 is present, it came from the network
166→    const source = result.signatureV2 ? 'network' : 'db_cache';
167→    this.metricsService.ipnsResolves.inc({ source });
168→
169→    // Include signature fields as all-or-nothing bundle for client verification
170→    const hasSigData = result.signatureV2 && result.data && result.pubKey;
171→    return {
172→      success: true,
173→      cid: result.cid,
174→      sequenceNumber: result.sequenceNumber,
175→      ...(hasSigData && {
176→        signatureV2: result.signatureV2,
177→        data: result.data,
178→        pubKey: result.pubKey,
179→      }),
180→    };
181→  }
182→}
